<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {Wallet,Users,Gift,FileText,ShieldCheck,ArrowUpRight,Copy,LogOut,RefreshCw,LockKeyhole} from 'lucide-vue-next'
import {user,account,site,api,refreshAccount,money,datetime,cents,key,labels} from '../api/account'
const props=defineProps<{page:string;walletMode:'deposit'|'withdraw'}>();const emit=defineEmits<{login:[];navigate:[page:string];notify:[message:string];logout:[]}>()
const busy=ref(false),error=ref(''),walletKind=ref(props.walletMode),amount=ref(''),note=ref(''),requestKey=ref(key()),oldPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),level=ref(0)
const title=computed(()=>({wallet:'我的钱包',commissions:'邀请与佣金',records:'订单记录',profile:'个人中心'}[props.page]??'个人中心'))
const inviteURL=computed(()=>`${location.origin}/?invite=${user.value?.invite_code??''}`)
const members=computed(()=>account.value?.members.filter(m=>!level.value||m.level===level.value)??[])
async function refresh(){try{await refreshAccount();error.value=''}catch(e){error.value=(e as Error).message}}
watch(()=>props.walletMode,v=>walletKind.value=v)
onMounted(()=>void refresh());watch(()=>props.page,()=>{error.value='';if(props.page==='wallet')walletKind.value=props.walletMode;void refresh()})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function request(){await action(async()=>{await api('/wallet/requests','POST',{kind:walletKind.value,amount_cents:cents(amount.value),note:note.value,key:requestKey.value});amount.value='';note.value='';requestKey.value=key();emit('notify','申请已提交，请等待审核');await refreshAccount()})}
async function claim(){await action(async()=>{const r=await api<{claimed_cents:number}>('/commissions/claim','POST',{});emit('notify',`佣金 ${money(r.claimed_cents)} 已转入余额`);await refreshAccount()})}
async function copy(){try{await navigator.clipboard.writeText(inviteURL.value);emit('notify','邀请链接已复制')}catch{error.value='无法自动复制，请选中下方链接手动复制'}}
async function changePassword(){await action(async()=>{if(newPassword.value!==confirmPassword.value)throw new Error('两次新密码不一致');await api('/auth/password','POST',{old_password:oldPassword.value,new_password:newPassword.value});user.value=null;account.value=null;emit('notify','密码已更新，请重新登录');emit('login')})}
</script>
<template><div class="account-page"><div class="page-heading"><div><p class="section-eyebrow">STARLIGHT · MY ACCOUNT</p><h1>{{title}}</h1><p>{{page==='commissions'?'分享邀请，查看三级团队与每一笔收益。':'账户、余额与记录，集中管理。'}}</p></div><button v-if="user" class="secondary-button" @click="refresh"><RefreshCw :size="16"/>刷新</button></div>
 <div v-if="!user" class="account-empty"><div class="auth-brand"><LockKeyhole :size="30"/></div><h2>登录你的星彩账户</h2><p>登录后查看余额、订单、邀请关系和佣金明细。</p><button class="primary-button" @click="emit('login')">登录 / 注册 <ArrowUpRight :size="17"/></button></div>
 <template v-else><div class="account-tabs"><button v-for="t in [{id:'profile',name:'账户',icon:ShieldCheck},{id:'wallet',name:'钱包',icon:Wallet},{id:'records',name:'订单',icon:FileText},{id:'commissions',name:'邀请佣金',icon:Users}]" :class="{active:page===t.id}" @click="emit('navigate',t.id)"><component :is="t.icon" :size="17"/>{{t.name}}</button></div><div v-if="error" class="form-error" role="alert">{{error}}</div>
 <template v-if="page==='profile'"><section class="account-identity"><div class="profile-avatar">{{user.username.slice(0,1).toUpperCase()}}</div><div><h2>{{user.username}} <span class="badge">{{user.role==='admin'?'管理员':'会员'}}</span></h2><p>邀请码 {{user.invite_code}} · 加入于 {{datetime(user.created_at)}}</p></div><button class="secondary-button" @click="emit('logout')"><LogOut :size="16"/>退出登录</button></section><div class="metric-grid"><article><small>可用余额</small><strong>{{money(user.balance_cents)}}</strong><span>账户可用金额</span></article><article><small>冻结金额</small><strong>{{money(user.frozen_cents)}}</strong><span>提现审核中</span></article><article><small>累计佣金</small><strong>{{money(account?.commission_total_cents)}}</strong><span>三级团队累计收益</span></article></div><div class="account-columns"><section class="surface"><h3>账户服务</h3><div class="service-links"><button @click="emit('navigate','wallet')"><Wallet/>钱包与资金流水<ArrowUpRight/></button><button @click="emit('navigate','commissions')"><Users/>邀请好友与佣金<ArrowUpRight/></button><button v-if="user.role==='admin'" @click="emit('navigate','admin')"><ShieldCheck/>管理员后台<ArrowUpRight/></button></div></section><section class="surface"><h3>修改登录密码</h3><form class="form-stack" @submit.prevent="changePassword"><label>原密码<input v-model="oldPassword" type="password" required maxlength="128" autocomplete="current-password"/></label><label>新密码<input v-model="newPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password" placeholder="至少10位"/></label><label>确认新密码<input v-model="confirmPassword" type="password" required minlength="10" maxlength="128" autocomplete="new-password"/></label><small>修改后，所有设备需要重新登录。</small><button class="primary-button" :disabled="busy">保存新密码</button></form></section></div></template>
 <template v-else-if="page==='wallet'"><div class="wallet-hero"><div><small>可用余额</small><strong>{{money(user.balance_cents)}}</strong><p>冻结余额 {{money(user.frozen_cents)}} · 每笔变动均有流水</p></div><Wallet :size="62"/></div><div class="account-columns"><section class="surface"><h3>资金申请</h3><div class="segmented"><button :class="{active:walletKind==='deposit'}" @click="walletKind='deposit'">充值申请</button><button :class="{active:walletKind==='withdraw'}" @click="walletKind='withdraw'">提现申请</button></div><form class="form-stack" @submit.prevent="request"><label>金额（元）<input v-model="amount" inputmode="decimal" required placeholder="0.00"/></label><label>{{walletKind==='deposit'?'到账凭证或说明':'收款方式与说明'}}<textarea v-model="note" required minlength="2" maxlength="500" rows="3" placeholder="填写供管理员核对的信息"/></label><p class="form-hint">{{walletKind==='deposit'?'提交申请不会自动入账，管理员核实后入账。':'提交后冻结对应余额；驳回自动解冻，审核通过后完成扣款。'}} 当前采用人工审核，未连接支付通道。</p><button class="primary-button" :disabled="busy">{{busy?'提交中…':'提交申请'}}</button></form></section><section class="surface"><h3>申请记录 <small>最近200条</small></h3><div class="compact-list"><article v-for="r in account?.requests" :key="r.id"><div><strong>{{labels[r.kind]}} · {{money(r.amount_cents)}}</strong><p>{{datetime(r.created_at)}}</p><p>{{r.review_note||r.note}}</p></div><span class="badge" :class="r.status">{{labels[r.status]}}</span></article><p v-if="!account?.requests.length" class="empty-copy">暂无申请记录</p></div></section></div><section class="surface"><h3>余额流水 <small>最近200条 · 金额单位：元</small></h3><div class="data-table-wrap"><table class="data-table"><thead><tr><th>时间</th><th>类型 / 说明</th><th>变动</th><th>可用余额</th><th>冻结余额</th></tr></thead><tbody><tr v-for="r in account?.ledger" :key="r.id"><td>{{datetime(r.created_at)}}</td><td>{{labels[r.kind]||r.kind}}<small>{{r.note}}</small></td><td :class="r.amount_cents>0?'positive':''">{{r.amount_cents>0?'+':''}}{{money(r.amount_cents)}}</td><td>{{money(r.balance_cents)}}</td><td>{{money(r.frozen_cents)}}</td></tr><tr v-if="!account?.ledger.length"><td colspan="5" class="empty-copy">暂无余额变动</td></tr></tbody></table></div></section></template>
 <template v-else-if="page==='commissions'"><section class="invite-hero"><div><p class="section-eyebrow">GROW TOGETHER</p><h2>邀请同行，精彩共享</h2><p>邀请关系最多向上计算三级，佣金来自团队已结算的有效投注。</p><p class="inviter-label">我的邀请人：<strong>{{account?.inviter?.username||'自主注册，无上级'}}</strong> · 我的邀请码</p><div class="invite-code">{{user.invite_code}}</div><div class="invite-link"><input :value="inviteURL" readonly aria-label="邀请链接" @focus="($event.target as HTMLInputElement).select()"/><button @click="copy"><Copy :size="16"/>复制链接</button></div></div><Users class="invite-art" :size="110"/></section><div class="metric-grid"><article><small>可领取佣金</small><strong>{{money(account?.commission_available_cents)}}</strong><button class="text-button" :disabled="busy||!account?.commission_available_cents" @click="claim">领取到余额 <ArrowUpRight :size="14"/></button></article><article><small>累计佣金</small><strong>{{money(account?.commission_total_cents)}}</strong><span>按分计算，尾数向下取整</span></article><article><small>三级团队人数</small><strong>{{account?.team_counts.reduce((a,b)=>a+b,0)||0}}</strong><span>一级 {{account?.team_counts[0]||0}} · 二级 {{account?.team_counts[1]||0}} · 三级 {{account?.team_counts[2]||0}}</span></article></div><div class="commission-levels"><article v-for="(rate,i) in site?.commission_bps" :key="i"><span>L{{i+1}}</span><div><small>{{['一级直邀','二级团队','三级团队'][i]}}</small><strong>{{rate/100}}<em>%</em></strong></div><p>{{account?.team_counts[i]||0}} 位成员</p></article></div><p class="form-hint">以上为当前比例。订单按下单时保存的比例计佣，撤销订单不计佣；比例为0时该级不产生佣金。</p><section class="surface"><h3>佣金明细 <small>最近200条</small></h3><div class="data-table-wrap"><table class="data-table"><thead><tr><th>来源 / 时间</th><th>层级</th><th>有效投注</th><th>比例</th><th>佣金</th><th>状态</th></tr></thead><tbody><tr v-for="c in account?.commissions" :key="c.id"><td>{{c.from_username}}<small>{{datetime(c.created_at)}} · 订单 {{Number(c.order_id)}}</small></td><td>{{c.level}}级</td><td>{{money(c.valid_stake_cents)}}</td><td>{{c.rate_bps/100}}%</td><td class="positive">+{{money(c.amount_cents)}}</td><td><span class="badge" :class="c.status">{{labels[c.status]}}</span></td></tr><tr v-if="!account?.commissions.length"><td colspan="6" class="empty-copy">暂无佣金。团队订单结算后，收益会显示在这里。</td></tr></tbody></table></div></section><section class="surface"><div class="surface-heading"><h3>我的团队 <small>最近200位</small></h3><select v-model.number="level" aria-label="团队层级"><option :value="0">全部层级</option><option v-for="n in 3" :value="n">{{n}}级成员</option></select></div><div class="compact-list"><article v-for="m in members" :key="m.id"><div><strong>{{m.username}}</strong><p>{{m.created_at}} 加入</p></div><span class="badge">{{m.level}}级成员</span></article><p v-if="!members.length" class="empty-copy">暂无团队成员，复制邀请链接分享给朋友。</p></div></section></template>
 <template v-else-if="page==='records'"><section class="surface"><h3>我的订单 <small>最近200条</small></h3><div class="account-orders"><article v-for="o in account?.orders" :key="o.id"><div class="order-item-heading"><div><strong>{{o.game_name}} · {{o.session_name}}</strong><p>{{datetime(o.created_at)}} · 第 {{o.issue}} 期</p></div><span class="badge" :class="o.status">{{labels[o.status]}}</span></div><div v-if="o.market_id" class="market-order-info"><strong>{{o.market_name}}</strong><span>下单赔率 {{((o.odds_milli??0)/1000).toFixed(3)}}</span><span v-if="o.outcome" class="badge" :class="o.outcome">{{({win:'中奖',lose:'未中',push:'和局退本'} as Record<string,string>)[o.outcome]}}</span><small v-if="o.result_numbers">开奖结果 {{o.result_numbers.join(' · ')}}</small></div><div v-else class="record-numbers"><b v-for="(n,i) in o.numbers" :key="i">{{o.session_id.startsWith('pk10')||o.session_id.startsWith('lhc')?String(n).padStart(2,'0'):n}}</b></div><div class="order-item-footer"><span><template v-if="o.multiplier">{{o.multiplier}} 倍 · </template>金额 <b>{{money(o.cost_cents)}}</b></span><span>派彩 {{money(o.payout_cents)}}</span></div><p v-if="o.note" class="form-hint">{{o.note}}</p></article><p v-if="!account?.orders.length" class="empty-copy">还没有订单，去大厅选择一款游戏吧。</p></div></section></template>
 </template></div></template>
